// IGES, April 2026, table 9, printed p91 (PDF page93). Informational only.
export const IGES={version:'iges-table9-v2-2026-04-v1',checkedAt:'2026-11-12',year:2024,variant:2,scaleMaximum:500000,total:1218275,recognized:{before:980885,model:764691,percent:-22.0},source:'https://www.gkv-spitzenverband.de/media/dokumente/pflegeversicherung/forschung/projekte_unterseiten/IGES_Entwicklung_Pflegepraevalenz_Abschlussbericht_final-2026-04-22.pdf#page=93',rows:[
  {grade:0,label:'Kein Pflegegrad',before:237390,model:453584,percent:91.1},
  {grade:1,label:'Pflegegrad 1',before:365938,model:379800,percent:3.8},
  {grade:2,label:'Pflegegrad 2',before:447931,model:287411,percent:-35.8},
  {grade:3,label:'Pflegegrad 3',before:136301,model:75171,percent:-44.8},
  {grade:4,label:'Pflegegrad 4',before:24551,model:16926,percent:-31.1},
  {grade:5,label:'Pflegegrad 5',before:6164,model:5383,percent:-12.7}
]};
const number=n=>new Intl.NumberFormat('de-DE').format(n);
const percent=n=>(n<0?'−':'+')+new Intl.NumberFormat('de-DE',{minimumFractionDigits:1,maximumFractionDigits:1}).format(Math.abs(n))+' %';
export function igesDetail(grade){
  const row=IGES.rows.find(r=>r.grade===grade)||IGES.rows[2];
  return `<div class="iges-detail-heading"><h3>${row.label}</h3><strong>${percent(row.percent)}</strong></div><dl><div><dt>Bisher · 2024</dt><dd>${number(row.before)}</dd></div><div><dt>IGES-Modell · Variante 2</dt><dd>${number(row.model)}</dd></div><div><dt>Veränderung der Fallzahl</dt><dd>${row.model-row.before<0?'−':'+'}${number(Math.abs(row.model-row.before))}</dd></div></dl>`;
}
export function igesSection(selected=2){
  return `<section class="reform-panel iges-panel" id="reform-auswirkungen" aria-labelledby="iges-heading"><div class="reform-panel-heading"><div><p class="eyebrow">05 / Die möglichen Auswirkungen</p><h2 id="iges-heading" tabindex="-1">Wie würde sich die Vergabe der Pflegegrade verändern?</h2></div></div><p class="reform-short-intro">Dieselben Erstbegutachtungen, andere Regeln: Grau zeigt die Ergebnisse von 2024, Blau die Neuberechnung im IGES-Modell.</p>
  <div class="iges-layout"><div class="iges-hero tone-ice"><div><strong>22 %</strong><h3>weniger Anerkennungen</h3></div><p>So viele Menschen weniger würden in der IGES-Modellrechnung bei einer Erstbegutachtung einen Pflegegrad erhalten.</p><span>Simulation mit Begutachtungsdaten aus 2024 · keine gesicherte Prognose</span></div>
  <div class="iges-data"><div class="iges-chart-header"><div class="iges-legend"><span><i class="iges-key-before" aria-hidden="true"></i>Bisher · 2024</span><span><i class="iges-key-model" aria-hidden="true"></i>IGES-Modell · neue Regeln</span></div><p>Je höher die Säule, desto mehr Menschen. Kategorie antippen für genaue Zahlen.</p></div>
  <div class="iges-scroll" tabindex="0" role="region" aria-label="Säulendiagramm; auf kleinen Bildschirmen seitlich scrollbar"><div class="iges-plot"><div class="iges-y-axis" aria-hidden="true"><span>500.000</span><span>250.000</span><span>0</span></div><div class="iges-chart" role="group" aria-label="Vergleich ausgewerteter Erstbegutachtungen aus 2024. Alle Balken haben dieselbe Skala von 0 bis 500.000 Fällen.">${IGES.rows.map(r=>`<button class="iges-row" data-iges-grade="${r.grade}" aria-pressed="${r.grade===selected}" aria-controls="iges-detail" aria-label="${r.label}: bisher ${number(r.before)}, Modell ${number(r.model)} Fälle, Veränderung ${percent(r.percent)}"><span class="iges-row-title"><span>${r.label}</span><strong>${percent(r.percent)}</strong></span><span class="iges-bar-pair" aria-hidden="true"><span class="iges-track"><span class="iges-bar iges-before" style="height:${r.before/IGES.scaleMaximum*100}%"></span></span><span class="iges-track"><span class="iges-bar iges-model" style="height:${r.model/IGES.scaleMaximum*100}%"></span></span></span></button>`).join('')}</div></div></div><p class="iges-mobile-hint">Seitlich wischen, um alle Pflegegrade zu vergleichen →</p><p class="iges-scale">Anzahl der Menschen · Prozentwerte unter den Kategorien zeigen die Veränderung gegenüber 2024</p><div class="iges-detail" id="iges-detail" aria-live="polite" aria-atomic="true">${igesDetail(selected)}</div></div></div>
  <div class="iges-summary"><h3>Weniger Menschen würden einen Pflegegrad erhalten.</h3><p>Besonders bei Pflegegrad 2 und 3 zeigt die Modellrechnung deutliche Rückgänge.</p></div>
  <details class="iges-reading"><summary>Die Veränderungen richtig einordnen</summary><div class="iges-interpretation"><p><strong>Pflegegrad 1: +3,8 %</strong>Verschiebungen aus höheren Pflegegraden können die Zahl erhöhen. Die Voraussetzungen werden dadurch nicht leichter.</p><p><strong>Kein Pflegegrad: +91,1 %</strong>Das ist der Anstieg dieser Fallzahl – nicht der Anteil aller Antragsteller ohne Pflegegrad.</p><p><strong>Insgesamt: −22,0 %</strong>Weniger Anerkennungen in den neu berechneten Erstgutachten. Kein Verlust von Pflegegraden bei 22 % der bereits Anerkannten.</p></div></details>
  <details class="reform-extra"><summary>Mehr erfahren: Daten & Einordnung</summary><div class="details-body"><p>Die Variante 2 kombiniert höhere Pflegegradgrenzen mit angepassten Umrechnungstabellen in Modul 1, 4 und 6. Sie rechnet ausgewertete Erstbegutachtungen aus 2024 neu; die Ergebnisse sind keine tatsächlichen Fallzahlen für 2027 und beziehen sich nicht auf alle Pflegebedürftigen oder die gesamte Bevölkerung.</p><p>Beide Spalten umfassen ${number(IGES.total)} Fälle. Pflegegrad 1–5 insgesamt: ${number(IGES.recognized.before)} bisher und ${number(IGES.recognized.model)} im Modell (−22,0 %). Die Prozentwerte sind relative Veränderungen, keine Prozentpunkte. Sie sind wie im Bericht auf eine Nachkommastelle gerundet.</p><p>Tabelle 9 schließt 1.241 Fälle mit fehlenden oder ungültigen Angaben und zusätzlich 50.243 Aktenlagen ohne Einzelpunkte bei nicht möglicher oder nicht zumutbarer persönlicher Befunderhebung aus. Die Tabelle beruht auf Daten des MD Bund. Es ist eine Simulation der Parameter des Expertenbeirats, keine Simulation eines bereits endgültig beschlossenen Gesetzes. Änderungen im parlamentarischen Verfahren sind möglich.</p></div></details><p class="iges-source"><a href="${IGES.source}" target="_blank" rel="noopener noreferrer">IGES, April 2026 · Tabelle 9, S. 91 · Variante 2</a></p></section>`;
}
export function handleIgesClick(event,state){
  const button=event.target.closest('[data-iges-grade]');if(!button)return false;
  const grade=Number(button.dataset.igesGrade);if(!IGES.rows.some(r=>r.grade===grade))return true;
  state.impactGrade=grade;document.querySelectorAll('[data-iges-grade]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.getElementById('iges-detail').innerHTML=igesDetail(grade);return true;
}
